"use client"

// The one pinned-stage primitive. A tall track, a sticky stage, and a number:
// --stage-p, 0..1 over the sticky dwell, driven by CSS (animation-timeline: view())
// so scrolling never touches React. `acts` divides the travel into checkpoints; the
// active act is the only React state, and it changes once per checkpoint, never per
// frame. <Act> exposes --act-p (0..1 within its own window) and --act-on (1 while on
// stage) as CSS, for opacity, transform, clip. State-shaped consumers (mount a phone
// when its act begins) read useAct().
// Renderers needing continuous JS progress opt into useScrollStageTimeline from
// scroll-stage-timeline. Its weighted beats replace these equal checkpoints.
//
// Desktop pinning is the default. `pin="all"` also enables phone-sized scenes;
// short landscape windows and reduced motion use the natural-height alternative.

import * as React from "react"
import "./scroll-stage.css"

const StageContext = React.createContext<{
  acts: number
  active: number
  seek: (index: number) => boolean
  track: React.RefObject<HTMLElement | null>
  pinnedQuery: string
} | null>(null)

/** Navigate the pinned story using the same act boundaries as useAct().
 * Returns false in stacked layouts, where the page provides its own navigation. */
export function useScrollStage() {
  const ctx = React.useContext(StageContext)
  if (!ctx) throw new Error("useScrollStage() outside <ScrollStage>")
  return ctx
}

/** The act on stage (0-based). Only valid inside <ScrollStage>. */
export function useAct(): number {
  const ctx = React.useContext(StageContext)
  if (!ctx) throw new Error("useAct() outside <ScrollStage>")
  return ctx.active
}

export interface ScrollStageProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "children"> {
  /** Checkpoints along the track. Act i is on stage past i/acts of the travel. */
  acts: number
  /** Scroll per act, a CSS length. Default 100svh. */
  pace?: string
  /** Extra travel after the last act, so it dwells. Default 40svh. */
  tail?: string
  /** Enable phone-sized scenes too; windows shorter than 36rem remain unpinned. */
  pin?: "desktop" | "all"
  /** Fires once per checkpoint change, never per frame. */
  onAct?: (act: number) => void
  /** The alternative layout below lg / under reduced motion (the acts stacked). */
  stacked?: React.ReactNode
  /** The stage: what stays pinned. */
  children: React.ReactNode
  as?: "section" | "article" | "div"
}

const PINNED = "(min-width: 64rem) and (prefers-reduced-motion: no-preference)"

export function ScrollStage({
  acts,
  pace,
  tail,
  pin = "desktop",
  onAct,
  stacked,
  children,
  as = "section",
  className,
  style,
  ...rest
}: ScrollStageProps) {
  if (!Number.isInteger(acts) || acts < 1)
    throw new Error(`ScrollStage: acts must be a positive integer, got ${acts}`)
  const track = React.useRef<HTMLElement>(null)
  const pinnedQuery =
    pin === "all"
      ? "(min-height: 36rem) and (prefers-reduced-motion: no-preference)"
      : PINNED
  const paceEl = React.useRef<HTMLDivElement>(null)
  const [active, setActive] = React.useState(0)
  const [engine, setEngine] = React.useState<"css" | "js">("css")
  const onActRef = React.useRef(onAct)
  onActRef.current = onAct

  React.useEffect(() => {
    const el = track.current
    const paceNode = paceEl.current
    if (!el || !paceNode) return
    const css = CSS.supports("animation-timeline: view()")
    setEngine(css ? "css" : "js")
    const pinned = window.matchMedia(pinnedQuery)
    let frame = 0
    let current = -1

    const sample = () => {
      frame = 0
      const rect = el.getBoundingClientRect()
      const pacePx = paceNode.offsetHeight
      let act: number
      if (!pinned.matches || pacePx === 0) {
        // Unpinned, or a collapsed track (pace 0): the completed state.
        act = acts - 1
        if (!css) el.style.removeProperty("--stage-p")
      } else {
        // ONE RULE for JS and CSS: act i is on stage past i/acts of the TRAVEL (the
        // track less one viewport), the same number `--stage-p` reports. Counting
        // paces here while the CSS counted travel lit an act's words before the stage
        // switched to it whenever a tail lengthened the track.
        const travel = rect.height - window.innerHeight
        const p = travel > 0 ? -rect.top / travel : rect.top < 0 ? 1 : 0
        const clamped = Math.min(1, Math.max(0, p))
        act = Math.min(acts - 1, Math.max(0, Math.floor(clamped * acts)))
        if (!css) el.style.setProperty("--stage-p", String(clamped))
      }
      if (act !== current) {
        current = act
        setActive(act)
        onActRef.current?.(act)
      }
    }
    const queue = () => {
      if (frame === 0) frame = requestAnimationFrame(sample)
    }
    let listening = false
    const listen = (on: boolean) => {
      if (on === listening) return
      listening = on
      if (on) {
        window.addEventListener("scroll", queue, { passive: true })
        window.addEventListener("resize", queue, { passive: true })
      } else {
        window.removeEventListener("scroll", queue)
        window.removeEventListener("resize", queue)
      }
    }
    // The listener exists only while the track is on screen.
    const io = new IntersectionObserver(([entry]) => {
      listen(entry?.isIntersecting ?? false)
      queue()
    })
    io.observe(el)
    pinned.addEventListener("change", queue)
    sample()
    return () => {
      io.disconnect()
      listen(false)
      pinned.removeEventListener("change", queue)
      cancelAnimationFrame(frame)
    }
  }, [acts, pinnedQuery])

  const seek = React.useCallback(
    (index: number) => {
      if (!Number.isInteger(index) || index < 0 || index >= acts)
        throw new Error(`ScrollStage: act ${index} outside 0..${acts - 1}`)
      const el = track.current
      if (!el || !window.matchMedia(pinnedQuery).matches) return false
      const rect = el.getBoundingClientRect()
      const travel = Math.max(0, rect.height - window.innerHeight)
      // Aim inside the act, not at a rounding-sensitive boundary. rect + scrollY
      // works in positioned wrappers where offsetTop is not a document coordinate.
      window.scrollTo({
        top: window.scrollY + rect.top + (travel * (index + 0.5)) / acts,
        behavior: "smooth",
      })
      return true
    },
    [acts, pinnedQuery],
  )
  const ctx = React.useMemo(
    () => ({ acts, active, seek, track, pinnedQuery }),
    [acts, active, seek, pinnedQuery],
  )
  return (
    <StageContext.Provider value={ctx}>
      {React.createElement(
        as,
        {
          ref: track,
          className: `ag-stage-track${className ? ` ${className}` : ""}`,
          "data-engine": engine,
          "data-pin": pin,
          "data-stacked": stacked !== undefined ? "" : undefined,
          style: {
            "--acts": acts,
            ...(pace && { "--pace": pace }),
            ...(tail && { "--tail": tail }),
            ...style,
          } as React.CSSProperties,
          ...rest,
        },
        <div ref={paceEl} className="ag-stage-pace" aria-hidden />,
        <div className="ag-stage">{children}</div>,
        stacked !== undefined && (
          <div className="ag-stage-stacked">{stacked}</div>
        ),
      )}
    </StageContext.Provider>
  )
}

export interface ActProps extends React.HTMLAttributes<HTMLDivElement> {
  /** 0-based checkpoint this element belongs to. */
  index: number
  as?: "div" | "section" | "article" | "figure"
}

/** A stage element bound to one act. Exposes two CSS numbers to its subtree:
 *  --act-p (0..1 across the act's own window of travel) and --act-on (1 while the act
 *  is on stage, 0 otherwise; the last act stays on through the tail). Drive opacity,
 *  transform, clip-path from them; do not read them in JS. */
export function Act({
  index,
  as = "div",
  className,
  style,
  ...rest
}: ActProps) {
  const ctx = React.useContext(StageContext)
  if (!ctx) throw new Error("<Act> outside <ScrollStage>")
  if (index < 0 || index >= ctx.acts)
    throw new Error(`<Act index={${index}}> outside 0..${ctx.acts - 1}`)
  const at = `(var(--stage-p) * var(--acts) - ${index})`
  const first = index === 0
  const last = index === ctx.acts - 1
  // The first act is on from the top of the track (it has no act before it to hand
  // over from), the last stays on through the tail; the ones between hold one window.
  const on =
    first && last
      ? "1"
      : first
        ? `clamp(0, (1 - ${at}) * 1000, 1)`
        : last
          ? `clamp(0, ${at} * 1000, 1)`
          : `min(clamp(0, ${at} * 1000, 1), clamp(0, (1 - ${at}) * 1000, 1))`
  return React.createElement(as, {
    className,
    "data-act": index,
    "data-on": ctx.active === index ? "" : undefined,
    style: {
      "--act-p": `clamp(0, ${at}, 1)`,
      "--act-on": on,
      ...style,
    } as React.CSSProperties,
    ...rest,
  })
}

/* scroll-stage: a tall TRACK whose sticky STAGE stays in view while the page scrolls
   past it. Progress (0..1 over the sticky dwell) is the inherited custom property
   --stage-p, set by a CSS scroll-driven animation (view() timeline, contain range =
   track top at viewport top → track bottom at viewport bottom). No JavaScript runs per
   frame; a browser without animation-timeline gets the same number from a scroll
   listener (data-engine="js"). Children read --stage-p (or --act-p via <Act>).

   Pinning happens at lg (64rem) and only when motion is welcome. Below that, or under
   prefers-reduced-motion, the track is its natural height, --stage-p is 1 (the
   completed state is the accessible one), and the `stacked` alternative shows. */

@property --stage-p {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

@keyframes ag-stage-p {
  from {
    --stage-p: 0;
  }
  to {
    --stage-p: 1;
  }
}

.ag-stage-track {
  position: relative;
  --stage-p: 1;
  --pace: 100svh;
  --tail: 40svh;
}

/* One unit of pace, measurable: the act clock divides the track's travel by it. */
.ag-stage-pace {
  position: absolute;
  top: 0;
  left: 0;
  width: 0;
  height: var(--pace);
  visibility: hidden;
  pointer-events: none;
}

@media (min-width: 64rem) and (prefers-reduced-motion: no-preference) {
  .ag-stage-track {
    --stage-p: 0;
    height: calc(var(--acts) * var(--pace) + var(--tail));
  }
  .ag-stage-track[data-engine="css"] {
    animation: ag-stage-p linear both;
    animation-timeline: view();
    animation-range: contain 0% contain 100%;
  }
  .ag-stage {
    position: sticky;
    top: var(--stage-top, 0px);
    display: flex;
    min-height: var(--stage-min-height, 100svh);
    align-items: var(--stage-align, center);
  }
  .ag-stage-track[data-stacked] > .ag-stage-stacked {
    display: none;
  }
}

@media not ((min-width: 64rem) and (prefers-reduced-motion: no-preference)) {
  .ag-stage-track[data-stacked] > .ag-stage {
    display: none;
  }
}

/* Small-screen pinning is explicit: the consumer must supply a scene that fits. */
@media (width < 64rem) and (min-height: 36rem) and (
    prefers-reduced-motion: no-preference
  ) {
  .ag-stage-track[data-pin="all"] {
    --stage-p: 0;
    height: calc(var(--acts) * var(--pace) + var(--tail));
  }
  .ag-stage-track[data-pin="all"][data-engine="css"] {
    animation: ag-stage-p linear both;
    animation-timeline: view();
    animation-range: contain 0% contain 100%;
  }
  .ag-stage-track[data-pin="all"] > .ag-stage {
    position: sticky;
    top: var(--stage-top, 0px);
    display: flex;
    min-height: var(--stage-min-height, 100svh);
    align-items: var(--stage-align, center);
  }
  .ag-stage-track[data-pin="all"] > .ag-stage-stacked {
    display: none;
  }
}

@media (height < 36rem) {
  .ag-stage-track[data-pin="all"] {
    height: auto;
    animation: none;
    --stage-p: 1;
  }
  .ag-stage-track[data-pin="all"] > .ag-stage {
    position: static;
    min-height: 0;
  }
  .ag-stage-track[data-pin="all"][data-stacked] > .ag-stage {
    display: none;
  }
  .ag-stage-track[data-pin="all"] > .ag-stage-stacked {
    display: block;
  }
}

"use client"

import * as React from "react"
import { useScrollStage } from "@/registry/base-nova/ui/scroll-stage"

export interface ScrollBeat {
  /** Relative scroll distance. A short finale might use .5. */
  span: number
  /** Fraction at which content finishes. Default .6. */
  play?: number
  /** Fraction at which the reading beat ends and transition starts. Default .85. */
  hold?: number
}

/** Pure choreography: content, reading dwell and movement share one position. */
export function scrollBeatFrame(
  position: number,
  beats: readonly ScrollBeat[],
) {
  let start = 0
  let active = beats.length - 1
  let offset = active
  const progress = beats.map((beat, i) => {
    const local = (position - start) / beat.span
    if (local >= 0 && local < 1) {
      active = i
      const hold = beat.hold ?? 0.85
      offset = Math.min(
        beats.length - 1,
        i + Math.max(0, (local - hold) / (1 - hold)),
      )
    }
    start += beat.span
    return Math.max(0, Math.min(1, local / (beat.play ?? 0.6)))
  })
  if (position <= 0) active = offset = 0
  return { active, offset, progress }
}

/** Opt-in JS driver for renderers such as transcripts that need exact content
 * progress. CSS-only scenes can keep using Act. No autoplay, no timed exit gates.
 * Keep beats stable (declare them outside the component). */
export function useScrollStageTimeline(
  beats: readonly ScrollBeat[],
  { top = 0, bottom = 0 }: { top?: number; bottom?: number } = {},
) {
  if (
    !beats.length ||
    beats.some(
      (b) =>
        !(b.span > 0) ||
        (b.play ?? 0.6) <= 0 ||
        (b.play ?? 0.6) > (b.hold ?? 0.85) ||
        (b.hold ?? 0.85) >= 1,
    )
  )
    throw new Error(
      "Scroll beats require positive spans and 0 < play <= hold < 1",
    )
  const { track, pinnedQuery } = useScrollStage()
  const span = beats.reduce((sum, beat) => sum + beat.span, 0)
  const [position, setPosition] = React.useState(0)
  const [ambient, setAmbient] = React.useState(0)

  React.useEffect(() => {
    const el = track.current
    const stage = el?.querySelector<HTMLElement>(".ag-stage")
    if (!el || !stage) return
    const media = matchMedia(pinnedQuery)
    let frame = 0
    let last = performance.now()
    let destination = scrollY
    let written = -1
    const bounds = () => {
      if (!media.matches) return null
      const rect = el.getBoundingClientRect()
      return {
        start: scrollY + rect.top,
        travel: Math.max(1, rect.height - innerHeight),
      }
    }
    const fit = () => {
      el.style.setProperty("--stage-min-height", "0px")
      el.style.setProperty(
        "--stage-top",
        `${Math.max(top, (innerHeight - stage.offsetHeight + top - bottom) / 2)}px`,
      )
    }
    const sample = () => {
      const range = bounds()
      if (!range) {
        setPosition(span)
        return
      }
      if (Math.abs(scrollY - written) > 1) destination = scrollY
      setPosition(
        Math.max(
          0,
          Math.min(span, ((scrollY - range.start) / range.travel) * span),
        ),
      )
      // Keep decoration moving through the scene's complete departure.
      const exit = scrollY + stage.getBoundingClientRect().bottom
      setAmbient(
        Math.max(
          0,
          ((Math.min(scrollY, exit) - range.start) / range.travel) * span,
        ),
      )
    }
    const tick = (now: number) => {
      frame = 0
      const range = bounds()
      if (!range) return
      const dt = Math.min(64, now - last)
      last = now
      const distance = destination - scrollY
      const step =
        Math.sign(distance) *
        Math.max(1, Math.abs(distance) * (1 - Math.exp(-dt / 55)))
      const limit = (range.travel / span) * 0.2
      written = Math.round(
        Math.abs(distance) < 1
          ? destination
          : scrollY + Math.max(-limit, Math.min(limit, step)),
      )
      window.scrollTo({ top: written, behavior: "instant" })
      sample()
      if (Math.abs(destination - written) >= 1)
        frame = requestAnimationFrame(tick)
    }
    const wheel = (event: WheelEvent) => {
      const range = bounds()
      if (
        !range ||
        event.ctrlKey ||
        Math.abs(event.deltaX) > Math.abs(event.deltaY)
      )
        return
      const delta =
        event.deltaY *
        (event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? innerHeight : 1)
      if (
        Math.max(scrollY, scrollY + delta) < range.start ||
        Math.min(scrollY, scrollY + delta) > range.start + range.travel
      )
        return
      event.preventDefault()
      if ((destination - scrollY) * delta < 0) destination = scrollY
      destination = Math.max(
        0,
        Math.min(
          document.documentElement.scrollHeight - innerHeight,
          destination + delta,
        ),
      )
      if (!frame) {
        last = performance.now()
        frame = requestAnimationFrame(tick)
      }
    }
    const resize = new ResizeObserver(fit)
    resize.observe(stage)
    const refresh = () => {
      fit()
      sample()
    }
    window.addEventListener("scroll", sample, { passive: true })
    window.addEventListener("wheel", wheel, { passive: false })
    window.addEventListener("resize", refresh)
    media.addEventListener("change", refresh)
    refresh()
    return () => {
      cancelAnimationFrame(frame)
      resize.disconnect()
      window.removeEventListener("scroll", sample)
      window.removeEventListener("wheel", wheel)
      window.removeEventListener("resize", refresh)
      media.removeEventListener("change", refresh)
      el.style.removeProperty("--stage-top")
      el.style.removeProperty("--stage-min-height")
    }
  }, [track, span, top, bottom, pinnedQuery])

  const seek = React.useCallback(
    (index: number) => {
      const beat = beats[index]
      if (!beat) throw new Error(`Unknown scroll beat: ${index}`)
      const el = track.current
      if (!el || !matchMedia(pinnedQuery).matches) return false
      const rect = el.getBoundingClientRect()
      const start = beats.slice(0, index).reduce((sum, b) => sum + b.span, 0)
      const reading = ((beat.play ?? 0.6) + (beat.hold ?? 0.85)) / 2
      window.scrollTo({
        top:
          scrollY +
          rect.top +
          ((rect.height - innerHeight) * (start + beat.span * reading)) / span,
        behavior: "smooth",
      })
      return true
    },
    [beats, track, span, pinnedQuery],
  )

  return { ...scrollBeatFrame(position, beats), position, ambient, seek }
}
